function isFlipedString(s1, s2) {
    return s1.length === s2.length && (s2 + s2).indexOf(s1) !== -1;
}

solutions.java:
class Solution {
    public boolean isFlipedString(String s1, String s2) {
        return s1.length() == s2.length() && (s1 + s1).contains(s2);
    }
}

